// Auto-generated from trigger/assets/intro_sound.mp3 (podcast intro sting), base64-embedded so
// it deploys with the pipeline. Regenerate this file if the asset changes.
const INTRO_MP3_BASE64 =
  "";

let cached: Buffer | null = null;
// The intro sting as an mp3 Buffer (decoded once, memoised).
export function introMp3(): Buffer {
  if (!cached) cached = Buffer.from(INTRO_MP3_BASE64, "base64");
  return cached;
}

// Real playback length of the intro sting (seconds), added to the word-count duration estimate for
// scrubber accuracy. Update if the asset is re-cut.
export const INTRO_SECONDS = 16.7;
